// Friendly aliases over the generated OpenAPI schema (schema.ts is generated by
// `npm run gen:api`; never edit it by hand). Import model types from here.
import type { components } from "./schema";

type S = components["schemas"];

export type Identity = S["Identity"];
export type Account = S["Account"];
export type Building = S["Building"];
export type Unit = S["Unit"];
export type Organization = S["Organization"];
export type OrganizationCreate = S["OrganizationCreate"];
export type Sender = S["Sender"];
export type MailAlias = S["MailAlias"];
export type UrgentReply = S["UrgentReply"];
export type Role = S["Role"];
export type Grant = S["Grant"];
export type GrantCreate = S["GrantCreate"];
export type ScopeType = S["ScopeType"];

// Minimised directory row (GET /accounts) and reveal-gated detail
// (GET /accounts/{id}?reveal=…). See docs/gdpr.md.
export type AccountSummary = S["AccountSummary"];
export type AccountDetail = S["AccountDetail"];

export type Ticket = S["Ticket"];
export type TicketCreate = S["TicketCreate"];
export type TicketStatus = S["TicketStatus"];
export type Event = S["Event"];
export type Attachment = S["Attachment"];

export type Metric = S["Metric"];
export type MetricMode = S["MetricMode"];
export type MetricValue = S["MetricValue"];
export type MetricValueCreate = S["MetricValueCreate"];
export type Score = S["Score"];
export type MetricDetail = S["MetricDetail"];
export type SlaInstance = S["SlaInstance"];
export type Snapshot = S["Snapshot"];
export type MonthlyReport = S["MonthlyReport"];
export type Sla = S["Sla"];

export type Survey = S["Survey"];
export type SurveyResponse = S["SurveyResponse"];
export type SiteInfo = S["SiteInfo"];

// A ticket detail response is a Ticket plus its event timeline.
export type TicketDetail = Ticket & { events: Event[] };
